using System;
using System.IO;
using UnityEngine;

namespace ItemRoulettePatcher
{
    /// <summary>
    /// The artifact icon. If <c>artifact_on.png</c> / <c>artifact_off.png</c> exist next to the plugin DLL they are used
    /// (custom art, no rebuild needed). Otherwise a small roulette wheel is drawn at runtime - that default icon was
    /// generated by an AI assistant (Claude), see the README.
    /// </summary>
    internal static class ArtifactIcon
    {
        private const int Size = 128;
        private const int Pockets = 12;

        public static Sprite Create(bool selected)
        {
            return LoadCustom(selected ? "artifact_on.png" : "artifact_off.png") ?? Draw(selected);
        }

        private static Sprite LoadCustom(string fileName)
        {
            try
            {
                var path = Path.Combine(Plugin.PluginDirectory ?? string.Empty, fileName);
                if (!File.Exists(path))
                {
                    return null;
                }

                var texture = new Texture2D(2, 2, TextureFormat.RGBA32, false)
                {
                    name = "ItemRoulettePatcher_" + fileName,
                    wrapMode = TextureWrapMode.Clamp,
                    filterMode = FilterMode.Bilinear,
                    hideFlags = HideFlags.HideAndDontSave,
                };
                if (!ImageConversion.LoadImage(texture, File.ReadAllBytes(path)))
                {
                    Plugin.Log.LogWarning($"{fileName} could not be read as an image; using the default icon.");
                    return null;
                }

                var sprite = Sprite.Create(texture, new Rect(0f, 0f, texture.width, texture.height), new Vector2(0.5f, 0.5f), 100f);
                sprite.hideFlags = HideFlags.HideAndDontSave;
                Plugin.Log.LogInfo($"Using custom artifact icon {fileName} ({texture.width}x{texture.height}).");
                return sprite;
            }
            catch (Exception e)
            {
                Plugin.Log.LogWarning($"Failed to load custom artifact icon {fileName}: {e.Message}");
                return null;
            }
        }

        private static Sprite Draw(bool selected)
        {
            var background = selected ? new Color(0.13f, 0.10f, 0.06f) : new Color(0.15f, 0.15f, 0.15f);
            var rim = selected ? new Color(1f, 0.82f, 0.28f) : new Color(0.46f, 0.46f, 0.46f);
            var red = selected ? new Color(0.78f, 0.12f, 0.12f) : new Color(0.30f, 0.30f, 0.30f);
            var dark = selected ? new Color(0.07f, 0.07f, 0.07f) : new Color(0.10f, 0.10f, 0.10f);

            var texture = new Texture2D(Size, Size, TextureFormat.RGBA32, false)
            {
                name = selected ? "ItemRoulettePatcherArtifactOn" : "ItemRoulettePatcherArtifactOff",
                wrapMode = TextureWrapMode.Clamp,
                filterMode = FilterMode.Bilinear,
                hideFlags = HideFlags.HideAndDontSave,
            };

            var pixels = new Color[Size * Size];
            var half = Size / 2f;
            for (var y = 0; y < Size; y++)
            {
                for (var x = 0; x < Size; x++)
                {
                    var dx = (x + 0.5f - half) / half;
                    var dy = (y + 0.5f - half) / half;
                    var radius = Mathf.Sqrt(dx * dx + dy * dy);

                    Color color;
                    if (radius < 0.15f)
                    {
                        color = dark;
                    }
                    else if (radius < 0.30f)
                    {
                        color = rim;
                    }
                    else if (radius < 0.40f)
                    {
                        color = dark;
                    }
                    else if (radius < 0.82f)
                    {
                        var angle = Mathf.Atan2(dy, dx) + Mathf.PI;
                        var pocket = Mathf.FloorToInt(angle / (2f * Mathf.PI) * Pockets) % Pockets;
                        color = pocket % 2 == 0 ? red : dark;
                    }
                    else if (radius < 0.97f)
                    {
                        color = rim;
                    }
                    else
                    {
                        color = background;
                    }

                    color.a = 1f;
                    pixels[y * Size + x] = color;
                }
            }

            texture.SetPixels(pixels);
            texture.Apply(false, false);

            var sprite = Sprite.Create(texture, new Rect(0f, 0f, Size, Size), new Vector2(0.5f, 0.5f), 100f);
            sprite.hideFlags = HideFlags.HideAndDontSave;
            return sprite;
        }
    }
}
